/* 必须定义在所有使用者之前。放在后面时 C99 以前的编译器会按隐式声明
 * 处理成返回 int——力矩被截成整数，而 gcc 14 起直接报错。 */
static float mpc_clamp1(float v, float lim)
{
    if (v >  lim) return  lim;
    if (v < -lim) return -lim;
    return v;
}

